```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/mitchellh/go-homedir"
	"gopkg.in/yaml.v2"
)

type StructInfo struct {
	Name     string `yaml:"name"`
	Fields   []Field `yaml:"fields"`
}

type Field struct {
	Type  string `yaml:"type"`
	Value string `yaml:"value"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the source file
	file, err := parser.ParseFile(token.NewFileSet(), sourceFile, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("Error parsing %s: %v\n", sourceFile, err)
		return
	}

	// Extract field information from the AST
	var structInfo StructInfo
	ast.Walk(func(node ast.Node) error {
		switch n := node.(type) {
		case *ast.Field:
			field := &StructInfo{
				Name: n.Name.Value,
			}
			for _, t := range n.Type.List {
				if f, ok := t.(*ast.FuncType); ok {
					field.Fields = append(field.Fields, Field{
						Type:  "string",
						Value: fmt.Sprintf("%s.%s", n.Name.Value, f.Params.List[0].Type.String()),
					})
				} else if f, ok := t.(*ast.StructType); ok {
					for i := 0; i < f.NumFields(); i++ {
						field.Fields = append(field.Fields, Field{
							Type:  "string",
							Value: fmt.Sprintf("%s.%s", n.Name.Value, f.Fields[i].Name),
						})
					}
				}
			}
			structInfo.Fields = append(structInfo.Fields, field)
		default:
			return nil
		}
		return nil
	}, file)

	// Write the generated Avro schema to a file
	schemaPath := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(schemaPath, []byte(yaml.Marshal(&structInfo)), 0644)
	if err != nil {
		fmt.Printf("Error writing %s: %v\n", schemaPath, err)
		return
	}

	fmt.Printf("Generated Avro schema saved to %s\n", schemaPath)
}
```

